//! Acceptance 2: `keys/{id}/secret` keeps the four Python outcomes.
//!
//! The expected bodies come from `tests/fixtures/rust_console_reads_rev1.json`,
//! generated by `tests/generate_rust_console_reads_fixture.py` from the real
//! Python cloud `usagesrv.Handler` and `share/management.py`.

mod support;

use std::path::PathBuf;

use serde_json::Value;

use support::*;

fn fixture_key_file(temp: &um_test_harness::TempDataDir, fixture: &Value) -> PathBuf {
    let hex = fixture["metadata"]["fixtureKeyHex"]
        .as_str()
        .expect("fixture key");
    let mut bytes = Vec::with_capacity(hex.len() / 2);
    let raw = hex.as_bytes();
    for pair in raw.chunks(2) {
        let high = (pair[0] as char).to_digit(16).expect("hex");
        let low = (pair[1] as char).to_digit(16).expect("hex");
        bytes.push((high * 16 + low) as u8);
    }
    let path = temp.path().join("share-secret.key");
    std::fs::write(&path, bytes).expect("write fixture key");
    path
}

fn console_with_secret(temp: &um_test_harness::TempDataDir, fixture: &Value) -> Console {
    let key_file = fixture_key_file(temp, fixture);
    start_console_with_seams(
        temp,
        |config| {
            config.share_store_file = Some(temp.path().join("share.db"));
            config.share_secret_key_file = Some(key_file.clone());
        },
        std::sync::Arc::new(StaticShareSeams::new()),
    )
}

#[test]
fn keys_list_matches_python_and_excludes_deleted_rows() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = console_with_secret(&temp, &fixture);
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/console/share-management/keys"),
    )
    .expect("request");
    assert_eq!(
        u64::from(response.status),
        fixture["shareKeys"]["status"].as_u64().unwrap()
    );
    assert_eq!(response.json(), fixture["shareKeys"]["body"]);
    assert_eq!(
        response.header("cache-control"),
        fixture["shareKeys"]["cacheControl"].as_str()
    );
    assert!(
        !response
            .body
            .windows(b"deleted".len())
            .any(|window| window == b"deleted"),
        "a deleted identity must not be listed"
    );
}

#[test]
fn secret_readback_matches_every_python_outcome() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = console_with_secret(&temp, &fixture);
    let cases = fixture["shareSecret"].as_object().expect("secret cases");
    let keys = &fixture["shareStatus"]["keys"];
    let key_id = |name: &str| -> String {
        let key = match name {
            "plaintext" | "plaintextExpected" | "versionConflict" | "invalidExpected"
            | "zeroExpected" => "active1",
            "rotated" => "rotated",
            "legacy" => "legacy",
            "undecryptable" => "undecryptable",
            "deleted" => "deleted",
            _ => return "no-such-key".to_string(),
        };
        keys[key]["key_id"].as_str().expect("key id").to_string()
    };
    let expected_version = |name: &str| -> Option<String> {
        match name {
            "plaintextExpected" => Some("1".to_string()),
            "versionConflict" => Some("2".to_string()),
            "invalidExpected" => Some("abc".to_string()),
            "zeroExpected" => Some("0".to_string()),
            "rotated" => Some("2".to_string()),
            _ => None,
        }
    };
    for (name, expected) in cases {
        let mut target = format!("/api/console/share-management/keys/{}/secret", key_id(name));
        if let Some(version) = expected_version(name) {
            target.push_str(&format!("?expected_row_version={version}"));
        }
        let response = client_request(console.addr, &ClientRequest::get(&target)).expect("request");
        assert_eq!(
            u64::from(response.status),
            expected["status"].as_u64().unwrap(),
            "{name}"
        );
        assert_eq!(response.json(), expected["body"], "{name}");
        assert_eq!(
            response.header("cache-control"),
            expected["cacheControl"].as_str(),
            "{name}"
        );
    }
}

#[test]
fn plaintext_only_rides_the_immediate_response() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = console_with_secret(&temp, &fixture);
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/console/share-management/keys/key-active-1/secret"),
    )
    .expect("request");
    let plaintext = fixture["shareSecret"]["plaintext"]["body"]["secret"]
        .as_str()
        .expect("secret");
    let body = response.json();
    assert_eq!(body["secret"], plaintext);
    assert!(!String::from_utf8_lossy(&response.body).contains("secret_hash"));
    assert!(!String::from_utf8_lossy(&response.body).contains("secret_blob"));
}

#[test]
fn secret_does_not_create_a_missing_share_store() {
    let fixture = reads_fixture();
    let temp = temp();
    let path = temp.path().join("missing-share.db");
    let key_file = fixture_key_file(&temp, &fixture);
    let store =
        um_console::share_read::ShareReadStore::with_options(path.clone(), None, Some(key_file));
    let error = store
        .secret("key-active-1", None)
        .expect_err("missing store");
    assert_eq!(error.status, 500);
    assert!(!path.exists());
}
